package mrpapermoon.whisper.mesh.dbimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Query@Daointerface WhispererDao {	@Insert(onConflict = OnConflictStrategy.REPLACE)	suspend fun insert(whisperer: WhispererEntity)	@Insert(onConflict = OnConflictStrategy.REPLACE)	suspend fun insertAll(whisperers: List<WhispererEntity>)	@Query("SELECT * FROM ${WhispererEntity.TABLE_NAME} WHERE whispererId = :whispererId")	suspend fun getWhisperer(whispererId: String): WhispererEntity?	@Query("SELECT * FROM ${WhispererEntity.TABLE_NAME} WHERE whispererId IN (:whispererIds)")	suspend fun getWhisperersByIds(whispererIds: List<String>): List<WhispererEntity>	@Query("SELECT * FROM ${WhispererEntity.TABLE_NAME}")	suspend fun getAllWhisperers(): List<WhispererEntity>}